using Microsoft.Extensions.AI;
using System.ComponentModel;

Console.WriteLine("Research Agent Starting...");

// Configure the AI client (set OPENAI_API_KEY and optionally OPENAI_MODEL env vars)
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

IChatClient innerClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient();

// Create tools
var researchTools = new ResearchTools();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Get the research topic from user
Console.Write("\nEnter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research the given topic thoroughly.

        Strategy:
        1. Search the web for relevant information using multiple queries
        2. Take notes on key findings as you go
        3. After gathering enough information, review your notes and provide a comprehensive summary

        Always take notes on important findings before moving to the next search.
        Perform at least 3 different searches to get broad coverage of the topic.
        End with a final summary that synthesizes all your notes.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await agent.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n===== RESEARCH SUMMARY =====\n");
Console.WriteLine(response);

Console.WriteLine("\n===== COLLECTED NOTES =====\n");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"• {note}");
}

/// <summary>Tools available to the research agent.</summary>
class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a query. Returns relevant search results.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");
        try
        {
            // Use a public search API (DuckDuckGo instant answer API)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _httpClient.GetStringAsync(url);

            var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Get abstract
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrEmpty(abstractText))
                results.Add($"Summary: {abstractText}");

            // Get related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a more specific or different query.";

            return string.Join("\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note taken: {note[..Math.Min(note.Length, 80)]}...");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during research.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

